def P(txt, style='BodyX'):
    return Paragraph(escape(txt).replace('\n','<br/>'), styles[style])
def R(txt, style='BodyX'):
    return Paragraph(txt, styles[style])
def code(txt):
    return Preformatted(txt, styles['CodeX'])
def bullet(txt):
    return Paragraph('&#8226; '+escape(txt), ParagraphStyle(name='b'+str(abs(hash(txt))), parent=styles['BodyX'], leftIndent=10, firstLineIndent=-7, spaceAfter=3))
def table(headers, rows, widths=None, tiny=False, repeat=1):
    sty=styles['Tiny' if tiny else 'Small']
    data=[[Paragraph(f'<b>{escape(str(x))}</b>',sty) for x in headers]]
    for row in rows:
        data.append([Paragraph(escape(str(x)).replace('\n','<br/>'),sty) for x in row])
    t=Table(data,colWidths=widths,repeatRows=repeat,hAlign='LEFT')
    pad = 2.5 if tiny else 4
    t.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),colors.white),
        ('GRID',(0,0),(-1,-1),.35,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),
        ('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,LIGHT]),('LEFTPADDING',(0,0),(-1,-1),pad),
        ('RIGHTPADDING',(0,0),(-1,-1),pad),('TOPPADDING',(0,0),(-1,-1),pad),('BOTTOMPADDING',(0,0),(-1,-1),pad)
    ])); return t

class GuideDoc(BaseDocTemplate):
    def __init__(self, filename):
        super().__init__(filename,pagesize=A4,rightMargin=14*mm,leftMargin=14*mm,topMargin=16*mm,bottomMargin=15*mm,title='Git Collaborator Access Manager - Architecture and Implementation Guide',author='Repository analysis generated by Codex')
        frame=Frame(self.leftMargin,self.bottomMargin,self.width,self.height,id='normal')
        wide=Frame(12*mm,12*mm,landscape(A4)[0]-24*mm,landscape(A4)[1]-24*mm,id='wide')
        self.addPageTemplates([PageTemplate(id='portrait',pagesize=A4,frames=[frame],onPage=self.header_footer),PageTemplate(id='landscape',pagesize=landscape(A4),frames=[wide],onPage=self.header_footer)])
        self.seen_h1 = False
    def beforeDocument(self):
        self.seen_h1 = False
    def header_footer(self, canvas, doc):
        canvas.saveState(); w,h=doc.pagesize
        if doc.page>1:
            canvas.setStrokeColor(LINE); canvas.line(14*mm,h-11*mm,w-14*mm,h-11*mm)
            canvas.setFont('Helvetica',6.7); canvas.setFillColor(MUTED)
            canvas.drawString(14*mm,h-8.5*mm,'GCAM Architecture and Implementation Guide')
            canvas.drawRightString(w-14*mm,8*mm,f'Page {doc.page}')
        canvas.restoreState()
    def afterFlowable(self, flowable):
        if isinstance(flowable, Paragraph):
            name=flowable.style.name
            if name in ('H1X','H2X'):
                if name == 'H2X' and not self.seen_h1:
                    return
                level=0 if name=='H1X' else 1
                if name == 'H1X':
                    self.seen_h1 = True
                text=flowable.getPlainText(); key='h%d-%s'%(level,re.sub('[^a-z0-9]+','-',text.lower()).strip('-'))
                self.canv.bookmarkPage(key); self.canv.addOutlineEntry(text,key,level=level,closed=False)
                self.notify('TOCEntry',(level,text,self.page,key))

